"""Vocabulary of each land-cover class, generated by an LLM from the class name and its fine land-cover names.

One prompt per class of `lc_classes` (same groups as `landcover_alignment.py` and `landcover_zeroshot.py`), built from a
short plain `definition` of the class, which asks for 1- to 3-word synonyms of the class and visible parts of it
that are observable from above at 10-20 m. If fewer than `min_terms`
distinct valid terms come back, the same prompt is sampled again, up to `max_attempts` times.

Output: `{output_dir}/vocab_landcover.csv` with columns class, class_name, term, n_gram. A term can appear in several
classes, but only once per class.
"""
from pathlib import Path
from typing import Dict, List

import hydra
import pandas as pd
from omegaconf import DictConfig, OmegaConf
from tqdm import tqdm
from transformers import set_seed

from experiments.concept_bottleneck.vocab.merge_vocab import key
from experiments.concept_bottleneck.vocab.vocab_gen_imp import clean, generate, load
from src.constants import CONFIG_PATH, LAND_COVER_DICT_IDS

PROMPT = """\
Build a list of simple terms for one land-cover class, as seen from above in satellite images of Canada \
(10-20 m pixels). The terms are concept names for a satellite-image model.

Land-cover class: {name}
Definition: {definition}

Give two kinds of terms:
1. Synonyms: other common words or short phrases for the same kind of land.
2. Visible parts: things that make up this class and can be seen from above, at least tens of metres \
across, with a clear colour, texture, shape or pattern.

Rules:
- Use simple, everyday English words. Never invent a word or glue words together.
- Each term has 1, 2 or 3 words (a hyphenated word counts as one word). Prefer short terms.
- Noun phrases only, lowercase, no punctuation other than hyphens.
- Do not start terms with the class name: give "parking lot", not "urban parking lot".
- No climate or region words (temperate, polar, sub-polar, boreal, arctic).
- No plant, crop or animal species names: describe vegetation by its form or use.
- Nothing that cannot be seen in an image: no sounds, heat, people, activities or underground things.
- No terms that mainly describe these other classes: {others}.
- No duplicates and no singular/plural variants.

Example for the class "orchard" (not in the list above):
orchard
fruit orchard
tree rows
grass strip
farm track
evenly spaced trees

Write exactly {k} terms for "{name}", one per line, then stop."""


def build_prompt(class_cfg: Dict, others: List[str], k: int) -> str:
    """The class `definition` if given, else its fine land-cover names."""
    definition = class_cfg.get("definition") or "; ".join(LAND_COVER_DICT_IDS[lc_id] for lc_id in class_cfg["ids"])
    return PROMPT.format(name=class_cfg["name"], definition=definition, others=", ".join(others), k=k)


def collect_terms(model, tok, prompt: str, cfg: DictConfig) -> List[str]:
    """Distinct valid terms in order of appearance, sampling until there are at least cfg.min_terms."""
    max_new_tokens = cfg.terms_requested * 10 + 100  # ~10 tokens/term incl. newline, with headroom
    terms: Dict[str, str] = {}  # singular/plural and word-order variants share a key
    for _ in range(cfg.max_attempts):
        text = generate(model, tok, prompt, 1, max_new_tokens, cfg.temperature, cfg.top_p)[0]
        for line in text.splitlines():
            term = clean(line)
            if term:
                terms.setdefault(key(term), term)
        if len(terms) >= cfg.min_terms:
            break
    return list(terms.values())


@hydra.main(version_base=None, config_path=str(CONFIG_PATH), config_name="vocab_gen_landcover")
def generate_landcover_vocab(cfg: DictConfig):
    assert cfg.terms_requested >= cfg.min_terms, "terms_requested must be >= min_terms"
    output_dir = Path(cfg.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    lc_classes = OmegaConf.to_container(cfg.lc_classes, resolve=True)
    model, tok = load(cfg.model_name)

    rows, short = [], []
    for class_key, class_cfg in tqdm(lc_classes.items(), desc="Land-cover classes"):
        set_seed(cfg.seed)  # A class's terms do not depend on which classes ran before it
        others = [c["name"] for k, c in lc_classes.items() if k != class_key]
        terms = collect_terms(model, tok, build_prompt(class_cfg, others, cfg.terms_requested), cfg)
        rows += [{"class": class_key, "class_name": class_cfg["name"], "term": term, "n_gram": len(term.split())}
                 for term in terms]
        counts = {n: sum(len(t.split()) == n for t in terms) for n in (1, 2, 3)}
        tqdm.write(f"{class_key}: {len(terms)} terms ({counts[1]} 1-gram, {counts[2]} 2-gram, {counts[3]} 3-gram)")
        if len(terms) < cfg.min_terms:
            short.append(f"{class_key} ({len(terms)})")

    path = output_dir / "vocab_landcover.csv"
    pd.DataFrame(rows).to_csv(path, index=False)
    print(f"Wrote {len(rows)} terms to {path}")
    if short:
        print(f"WARNING: fewer than {cfg.min_terms} terms after {cfg.max_attempts} attempts: {', '.join(short)}")


if __name__ == "__main__":
    generate_landcover_vocab()
